grid=[[1]*13 for _ in range(21)]
# Preserve the seed and stamp its non-background cells around each 8 marker.
markers=[(2,6),(2,10),(4,3),(7,6),(7,10),(10,1),(10,9),(17,2),(17,9)]
pattern={(-1,-1):3,(-1,0):5,(-1,1):3,(0,0):5,(0,1):3,(1,1):3}
for r,c in markers:
    for (dr,dc),v in pattern.items(): grid[r+dr][c+dc]=v
for row in grid: print(row)
assert len(grid)==21 and all(len(r)==13 for r in grid)

g=[[1]*13 for _ in range(21)]
# Exact seed in rows 13..15, cols 4..6, background 1 transparent; center anchor is 5.
seed=[[3,5,3],[1,5,3],[1,1,3]]
markers=[(2,6),(2,10),(4,3),(7,6),(7,10),(10,1),(10,9),(17,2),(17,9)]
for r,c in markers:
  for dr in range(3):
    for dc in range(3):
      v=seed[dr][dc]
      if v!=1:
        rr,cc=r+dr-1,c+dc-1
        if 0<=rr<21 and 0<=cc<13: g[rr][cc]=v
# Preserve original seed
for dr in range(3):
  for dc in range(3): g[13+dr][4+dc]=seed[dr][dc]
assert len(g)==21 and all(len(row)==13 for row in g)
for row in g: print(' '.join(map(str,row)))
